    warmup_epochs = 5
    if epoch <= warmup_epochs:
        lr_scale = epoch / warmup_epochs
    else:
        progress = (epoch - warmup_epochs) / max(1, NUM_EPOCHS - warmup_epochs)
        lr_scale = 0.2 + 0.8 * 0.5 * (1.0 + math.cos(math.pi * progress))
